head.script:
scwin.init = function() {
    var jsonData = [{
            "col1": "test",
            "col2": "test2"
        },
        {
            "col1": "test",
            "col2": "test2"
        },
        {
            "col1": "test",
            "col2": "test2"
        },
        {
            "col1": "test",
            "col2": "test2"
        },
        {
            "col1": "test",
            "col2": "test2"
        }
    ];
    dataList1.setJSON(jsonData);
};
scwin.trigger1_onclick = function(e) {
    grd.setColumnOrder(["col3", "col2", "col1"]);
};
scwin.trigger2_onclick = function(e) {
    grd.setColumnOrder(["col2", "col1", "col3"]);
};
scwin.trigger3_onclick = function(e) {
    grd.setColumnOrder(["col1", "col3", "col2"]);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 grd 의 columnMove 부분을 확인한다.
    //1. In the Source tab, check the columnMove part of grd.
    //Verify step 1. columnMove = "true"
    //Test step 2. columnMoveWithFooter 부분을 확인한다.
    //2. Check columnMoveWithFooter.
    //Verify step 2. columnMoveWithFooter = "true"
    //Test step 3. 브라우저에서 columnMoveWithFooter ("col3","col2","col1") 버튼을 클릭한다.
    //3. In your browser, click the columnMoveWithFooter ("col3", "col2", "col1") button.
    //Verify step 3. The column and footer are changed in col3 / col2 / col1 order.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridHeaderStyle_0 th')[0].innerText == 'col3'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridHeaderStyle_0 th')[1].innerText == 'col2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridHeaderStyle_0 th')[2].innerText == 'col1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridFooterStyle_0 td')[0].innerText == 'col3'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridFooterStyle_0 td')[1].innerText == 'col2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridFooterStyle_0 td')[2].innerText == 'col1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. columnMoveWithFooter ('col2','col1','col3') 버튼을 클릭한다.
    //4. Click the columnMoveWithFooter ('col2', 'col1', 'col3') button.
    //Verify step 4. The column and footer are changed to col2 / col1 / col3.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridHeaderStyle_0 th')[0].innerText == 'col2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridHeaderStyle_0 th')[1].innerText == 'col1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridHeaderStyle_0 th')[2].innerText == 'col3'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridFooterStyle_0 td')[0].innerText == 'col2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridFooterStyle_0 td')[1].innerText == 'col1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridFooterStyle_0 td')[2].innerText == 'col3'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 5. columnMoveWithFooter ('col1','col3','col2') 버튼을 클릭한다.
    //5. Click the columnMoveWithFooter ('col1', 'col3', 'col2') button.
    //Verify step 5. The column and footer are changed in col1 / col3 / col2 order.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridHeaderStyle_0 th')[0].innerText == 'col1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridHeaderStyle_0 th')[1].innerText == 'col3'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridHeaderStyle_0 th')[2].innerText == 'col2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridFooterStyle_0 td')[0].innerText == 'col1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridFooterStyle_0 td')[1].innerText == 'col3'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.gridFooterStyle_0 td')[2].innerText == 'col2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 10-Apr-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
